import Foundation

extension DoitCurriculum {
    static let english: [CurriculumEntry] = [
        // MARK: - 초등

        ce(.elementary, "알파벳과 파닉스", ["알파벳", "Alphabet"], "알파벳은 영어를 적는 26개의 글자예요. 글자마다 대문자(A)와 소문자(a)가 있어요. 문장의 첫 글자와 사람 이름, 나라 이름은 대문자로 시작하고, 나 자신을 뜻하는 I는 늘 대문자로 써요.\n예: My name is Mina. (내 이름은 미나예요.)"),
        ce(.elementary, "알파벳과 파닉스", ["파닉스", "Phonics"], "파닉스는 글자와 소리의 관계를 익혀서 처음 보는 단어도 소리 내어 읽을 수 있게 하는 방법이에요. 글자의 이름과 글자가 내는 소리는 달라요. 예를 들어 b의 이름은 '비'지만 소리는 [브]에 가까워요.\n예: b + a + t → bat (방망이, 박쥐)"),
        ce(.elementary, "알파벳과 파닉스", ["모음과 자음", "Vowels and Consonants"], "영어 알파벳 중 a, e, i, o, u 다섯 글자를 모음, 나머지 21글자를 자음이라고 해요. 모음은 단어 소리의 중심이 되고, 자음은 모음 앞뒤에 붙어 소리를 만들어요. y는 단어에 따라 모음처럼 소리 나기도 해요.\n예: gym, my에서 y는 모음 소리를 내요."),
        ce(.elementary, "알파벳과 파닉스", ["단모음", "Short Vowel"], "단모음은 모음이 짧게 나는 소리예요. 자음-모음-자음으로 된 짧은 단어에서 주로 나요. a는 [애], e는 [에], i는 [이], o는 [아], u는 [어]에 가깝게 소리 나요.\n예: cat, bed, pig, hot, cup"),
        ce(.elementary, "알파벳과 파닉스", ["장모음", "Long Vowel", "매직 e", "Magic e"], "장모음은 모음이 자기 알파벳 이름대로 소리 나는 것이에요. 단어 끝에 소리 나지 않는 e가 붙으면 앞의 모음이 장모음으로 바뀌는 경우가 많아서 이 e를 '매직 e'라고 불러요.\n예: cap(모자) → cape(망토), kit → kite(연), hop → hope(희망)"),
        ce(.elementary, "알파벳과 파닉스", ["이중자음", "Consonant Digraph"], "두 자음이 만나 하나의 새로운 소리를 내는 것을 이중자음(다이그래프)이라고 해요. sh는 [쉬], ch는 [취], th는 [θ]나 [ð], ph는 [f], wh는 대개 [w]처럼 소리 나요.\n예: ship, chair, three, phone, whale"),
        ce(.elementary, "알파벳과 파닉스", ["연속자음", "Consonant Blend", "자음군"], "두세 개의 자음이 이어지지만 각 자음 소리가 살아 있는 것을 연속자음(블렌드)이라고 해요. 이중자음과 달리 원래 소리를 빠르게 이어서 읽어요.\n예: black(bl), star(st), tree(tr), spring(spr)"),

        ce(.elementary, "인사와 자기소개", ["인사 표현", "Greetings"], "만날 때는 Hello나 Hi라고 인사해요. 아침에는 Good morning, 오후에는 Good afternoon, 저녁에는 Good evening이라고 해요. Good night은 밤에 헤어지거나 잠자리에 들 때 하는 인사예요.\n예: Good morning, Mr. Kim! (안녕하세요, 김 선생님!)"),
        ce(.elementary, "인사와 자기소개", ["자기소개", "Self-introduction"], "자기소개를 할 때는 이름, 나이, 사는 곳, 좋아하는 것을 말해요. My name is ~. 또는 I'm ~.으로 이름을 말하고, I'm ~ years old.로 나이를 말해요.\n예: Hi, I'm Junho. I'm eleven years old. I'm from Korea. (안녕, 나는 준호야. 열한 살이고 한국에서 왔어.)"),
        ce(.elementary, "인사와 자기소개", ["안부 묻기", "How are you?"], "How are you?는 '잘 지내?', '기분 어때?'라고 안부를 묻는 말이에요. I'm fine.이나 I'm good.처럼 대답하고, And you?로 상대에게 되물을 수 있어요.\n예: A: How are you? B: I'm great, thanks. And you? (A: 잘 지내? B: 아주 좋아, 고마워. 너는?)"),
        ce(.elementary, "인사와 자기소개", ["처음 만났을 때 인사", "Nice to meet you"], "처음 만난 사람에게는 Nice to meet you.(만나서 반가워요.)라고 인사해요. 대답할 때는 끝에 too를 붙여 Nice to meet you, too.라고 해요.\n예: A: I'm Sora. Nice to meet you. B: Nice to meet you, too. (A: 나는 소라야. 만나서 반가워. B: 나도 만나서 반가워.)"),
        ce(.elementary, "인사와 자기소개", ["헤어질 때 인사", "Goodbye"], "헤어질 때는 Goodbye나 Bye라고 해요. 다시 만날 때를 넣어 See you later.(나중에 봐.), See you tomorrow.(내일 봐.)라고도 해요. Have a nice day.(좋은 하루 보내.)도 자주 써요.\n예: Bye, Minji! See you tomorrow. (안녕, 민지야! 내일 봐.)"),
        ce(.elementary, "인사와 자기소개", ["감사와 사과 표현", "Thank you", "Sorry"], "고마울 때는 Thank you.나 Thanks.라고 하고, 대답은 You're welcome.(천만에요.)이라고 해요. 미안할 때는 I'm sorry.라고 하고, 대답은 That's okay.나 It's all right.(괜찮아요.)라고 해요.\n예: A: Sorry, I'm late. B: That's okay. (A: 늦어서 미안해. B: 괜찮아.)"),
        ce(.elementary, "인사와 자기소개", ["좋아하는 것 말하기", "I like ~"], "좋아하는 것은 I like ~.로 말해요. 셀 수 있는 것을 일반적으로 좋아한다고 할 때는 복수형을 써요. 상대에게 물을 때는 Do you like ~?라고 하고, Yes, I do. 또는 No, I don't.로 대답해요.\n예: I like dogs. Do you like dogs? (나는 개를 좋아해. 너도 개 좋아해?)"),

        ce(.elementary, "be동사와 대명사", ["be동사", "Be Verb"], "be동사는 '~이다', '~(에) 있다'라는 뜻의 동사예요. 현재형은 주어에 따라 달라져서 I에는 am, you와 복수 주어에는 are, he·she·it 같은 3인칭 단수에는 is를 써요.\n예: I am a student. They are in the classroom. (나는 학생이에요. 그들은 교실에 있어요.)"),
        ce(.elementary, "be동사와 대명사", ["인칭대명사", "Personal Pronoun"], "인칭대명사는 사람이나 사물을 대신 가리키는 말이에요. 주어로 쓸 때는 I, you, he, she, it, we, they를 쓰고, 목적어로 쓸 때는 me, you, him, her, it, us, them을 써요.\n예: I like him. He likes me, too. (나는 그를 좋아해요. 그도 나를 좋아해요.)"),
        ce(.elementary, "be동사와 대명사", ["be동사의 부정문", "Be Verb Negative"], "be동사 문장을 부정할 때는 be동사 뒤에 not을 붙여요. is not은 isn't, are not은 aren't로 줄여 쓸 수 있어요. am not은 보통 줄이지 않고 I'm not으로 써요.\n예: He isn't tired. I'm not hungry. (그는 피곤하지 않아요. 나는 배고프지 않아요.)"),
        ce(.elementary, "be동사와 대명사", ["be동사의 의문문", "Be Verb Question"], "be동사 의문문은 be동사를 주어 앞으로 보내고 끝에 물음표를 붙여요. 긍정 대답은 Yes, 주어 + be동사., 부정 대답은 No, 주어 + be동사 + not.으로 해요. 긍정 대답에서는 Yes, I'm.처럼 줄여 쓰지 않아요.\n예: A: Are you a student? B: Yes, I am. (A: 너는 학생이니? B: 응, 그래.)"),
        ce(.elementary, "be동사와 대명사", ["축약형", "Contraction"], "축약형은 두 단어를 줄여 쓴 형태로, 생략된 글자 자리에 아포스트로피(')를 찍어요. 말할 때나 편한 글에서 자주 써요.\n예: I am → I'm, you are → you're, it is → it's, do not → don't, cannot → can't"),
        ce(.elementary, "be동사와 대명사", ["지시대명사", "This and That", "These and Those"], "가까이 있는 하나는 this, 멀리 있는 하나는 that으로 가리켜요. 여러 개일 때는 가까운 것은 these, 먼 것은 those를 쓰고, be동사도 복수형 are를 써요.\n예: This is my bag. Those are your shoes. (이것은 내 가방이에요. 저것들은 네 신발이에요.)"),
        ce(.elementary, "be동사와 대명사", ["소유격", "Possessive"], "소유격은 '~의'라는 뜻으로 명사 앞에 써요. my, your, his, her, its, our, their가 있고, 사람 이름이나 명사 뒤에는 's를 붙여요. it's(it is)와 소유격 its를 헷갈리지 않도록 주의해요.\n예: This is Tom's book. Its cover is blue. (이것은 톰의 책이에요. 그 표지는 파란색이에요.)"),

        ce(.elementary, "일반동사 현재형", ["일반동사", "General Verb", "Action Verb"], "일반동사는 be동사와 조동사를 뺀 나머지 동사로, 주로 동작이나 상태를 나타내요. 현재형은 습관, 반복되는 일, 변하지 않는 사실을 말할 때 써요.\n예: I play soccer every Saturday. (나는 토요일마다 축구를 해요.)"),
        ce(.elementary, "일반동사 현재형", ["3인칭 단수 현재형", "Third Person Singular", "동사의 -s"], "주어가 he, she, it이나 단수 명사이고 현재 시제이면 일반동사 끝에 -s를 붙여요. s, x, sh, ch, o로 끝나면 -es를, 자음 + y로 끝나면 y를 i로 바꾸고 -es를 붙여요. have는 has로 바뀌어요.\n예: She watches TV. He studies English. (그녀는 TV를 봐요. 그는 영어를 공부해요.)"),
        ce(.elementary, "일반동사 현재형", ["일반동사의 부정문", "do not", "does not"], "일반동사 현재형을 부정할 때는 동사 앞에 do not(don't)이나 does not(doesn't)을 써요. 주어가 3인칭 단수이면 doesn't를 쓰고, 뒤의 동사는 반드시 동사원형으로 써요.\n예: He doesn't like carrots. (○) He doesn't likes carrots. (×) (그는 당근을 좋아하지 않아요.)"),
        ce(.elementary, "일반동사 현재형", ["일반동사의 의문문", "Do question", "Does question"], "일반동사 현재형 의문문은 Do나 Does를 문장 맨 앞에 두고, 주어 뒤에 동사원형을 써요. 대답은 Yes, 주어 + do/does. 또는 No, 주어 + don't/doesn't.로 해요.\n예: A: Does your brother play the piano? B: Yes, he does. (A: 네 남동생은 피아노를 치니? B: 응, 쳐.)"),
        ce(.elementary, "일반동사 현재형", ["명령문", "Imperative"], "명령문은 상대에게 지시하거나 부탁하는 문장으로, 주어 없이 동사원형으로 시작해요. '~하지 마'는 Don't + 동사원형, '~하자'는 Let's + 동사원형으로 말해요. please를 붙이면 더 공손해져요.\n예: Open the door, please. Don't run. Let's go! (문 좀 열어 주세요. 뛰지 마. 가자!)"),

        ce(.elementary, "명사와 관사", ["명사", "Noun"], "명사는 사람, 동물, 사물, 장소, 생각 등의 이름을 나타내는 말이에요. 문장에서 주어, 목적어, 보어로 쓰여요.\n예: Mina has a cat in her house. (미나는 집에서 고양이를 키워요.) → Mina, cat, house가 명사예요."),
        ce(.elementary, "명사와 관사", ["셀 수 있는 명사와 셀 수 없는 명사", "Countable Noun", "Uncountable Noun"], "하나, 둘 셀 수 있는 명사는 a/an을 붙이거나 복수형으로 쓸 수 있어요. water, milk, money, rice처럼 셀 수 없는 명사는 a/an을 붙이지 않고 복수형도 없어요. 양을 셀 때는 a glass of, a piece of 같은 단위를 써요.\n예: a cup of tea, two pieces of paper (차 한 잔, 종이 두 장)"),
        ce(.elementary, "명사와 관사", ["명사의 복수형", "Plural Noun"], "명사가 둘 이상일 때는 보통 끝에 -s를 붙여요. s, x, sh, ch로 끝나면 -es를, 자음 + y로 끝나면 y를 i로 바꾸고 -es를, f나 fe로 끝나면 대개 v로 바꾸고 -es를 붙여요. o로 끝나는 단어는 potatoes처럼 -es를 붙이는 것과 pianos처럼 -s만 붙이는 것이 있어요.\n예: book → books, box → boxes, baby → babies, leaf → leaves"),
        ce(.elementary, "명사와 관사", ["불규칙 복수형", "Irregular Plural"], "규칙을 따르지 않고 모양이 바뀌거나 단수와 복수가 같은 명사도 있어요. 이런 단어는 따로 외워 두어야 해요.\n예: man → men, woman → women, child → children, tooth → teeth, foot → feet, mouse → mice, sheep → sheep, fish → fish"),
        ce(.elementary, "명사와 관사", ["부정관사 a/an", "Indefinite Article"], "a/an은 셀 수 있는 명사 하나 앞에 쓰는 말로 '하나의', '어떤'이라는 뜻이에요. 철자가 아니라 첫 소리를 기준으로, 모음 소리 앞에는 an, 자음 소리 앞에는 a를 써요.\n예: an apple, an hour(h가 소리 나지 않음), a university(첫소리가 [j]), a dog"),
        ce(.elementary, "명사와 관사", ["정관사 the", "Definite Article"], "the는 서로 알고 있는 특정한 것을 가리킬 때 써요. 앞에서 이미 말한 것, 세상에 하나뿐인 것(the sun, the moon), 악기 이름 앞에 주로 붙여요. 식사나 운동 경기 이름 앞에는 보통 쓰지 않아요.\n예: I saw a cat. The cat was black. (나는 고양이를 봤어요. 그 고양이는 검은색이었어요.)"),

        ce(.elementary, "위치와 시간 전치사", ["위치 전치사", "Preposition of Place"], "위치 전치사는 명사 앞에서 사물이 어디에 있는지 나타내요. in은 '~ 안에', on은 '~ 위에(표면에 닿아서)', under는 '~ 아래에'라는 뜻이에요.\n예: The ball is under the chair. The book is on the desk. (공은 의자 아래에 있어요. 책은 책상 위에 있어요.)"),
        ce(.elementary, "위치와 시간 전치사", ["여러 가지 위치 표현", "next to", "between", "in front of"], "next to는 '~ 옆에', behind는 '~ 뒤에', in front of는 '~ 앞에', between A and B는 'A와 B 사이에'라는 뜻이에요. 길을 묻고 답할 때도 자주 써요.\n예: The bank is between the school and the park. (은행은 학교와 공원 사이에 있어요.)"),
        ce(.elementary, "위치와 시간 전치사", ["시간 전치사 at/on/in", "Preposition of Time"], "시각 앞에는 at, 요일과 날짜 앞에는 on, 월·연도·계절처럼 긴 기간 앞에는 in을 써요. in the morning처럼 하루 중 때에도 in을 쓰지만, 밤은 at night라고 해요.\n예: at 7 o'clock, on Monday, on May 5, in July, in 2025, in winter"),
        ce(.elementary, "위치와 시간 전치사", ["위치 묻고 답하기", "Where is ~?"], "물건이나 장소가 어디 있는지 물을 때는 Where is ~?를 써요. 여러 개일 때는 Where are ~?라고 해요. 대답은 It's + 위치 전치사 + 장소. 또는 They're ~.로 해요.\n예: A: Where is my cap? B: It's on the bed. (A: 내 모자 어디 있어? B: 침대 위에 있어.)"),

        ce(.elementary, "기초 의문문", ["의문사", "Question Words", "Wh-question"], "의문사는 구체적인 정보를 묻는 말로 문장 맨 앞에 와요. who(누구), what(무엇), when(언제), where(어디), why(왜), how(어떻게), which(어느 것)가 있어요. 의문사 의문문에는 Yes나 No로 대답하지 않아요.\n예: A: Where do you live? B: I live in Busan. (A: 어디 살아? B: 부산에 살아.)"),
        ce(.elementary, "기초 의문문", ["What 의문문", "What is this?"], "What은 '무엇'을 묻는 의문사예요. 사물을 물을 때는 What's this?, 이름은 What's your name?, 좋아하는 것은 What's your favorite ~?라고 물어요.\n예: A: What's your favorite color? B: It's blue. (A: 가장 좋아하는 색이 뭐야? B: 파란색이야.)"),
        ce(.elementary, "기초 의문문", ["How 의문문", "How old are you?"], "How는 '어떻게', '얼마나'를 묻는 의문사예요. 나이는 How old ~?, 키는 How tall ~?, 방법은 How do you ~?로 물어요.\n예: A: How do you go to school? B: I go to school by bus. (A: 학교에 어떻게 가? B: 버스 타고 가.)"),
        ce(.elementary, "기초 의문문", ["How many와 How much", "How many", "How much"], "How many는 셀 수 있는 명사의 개수를 물을 때 쓰고, 뒤에 복수 명사가 와요. How much는 셀 수 없는 명사의 양이나 물건의 가격을 물을 때 써요.\n예: How many pencils do you have? How much is this cap? (연필이 몇 자루 있니? 이 모자는 얼마예요?)"),
        ce(.elementary, "기초 의문문", ["할 수 있는 것 말하기", "I can ~", "Can you ~?"], "할 수 있는 일은 I can + 동사원형으로 말하고, 할 수 없는 일은 I can't + 동사원형으로 말해요. Can you ~?로 물으면 Yes, I can. 또는 No, I can't.로 대답해요.\n예: A: Can you swim? B: Yes, I can. (A: 너 수영할 수 있어? B: 응, 할 수 있어.)"),

        ce(.elementary, "숫자·요일·날씨", ["기수", "Cardinal Number"], "기수는 one, two, three처럼 개수를 나타내는 수예요. 13부터 19까지는 -teen으로 끝나고, 20, 30처럼 십 단위는 -ty로 끝나요. thirteen(13)과 thirty(30)는 강세 위치가 달라서 잘 듣고 구별해야 해요.\n예: twenty-one(21), forty(40, fourty가 아님), one hundred(100)"),
        ce(.elementary, "숫자·요일·날씨", ["서수", "Ordinal Number"], "서수는 first(첫째), second(둘째), third(셋째)처럼 순서를 나타내는 수예요. 대부분 기수에 -th를 붙이지만 fifth, ninth, twelfth처럼 철자가 바뀌는 것도 있어요. 날짜를 말할 때도 서수를 써요.\n예: My birthday is May 3rd(third). (내 생일은 5월 3일이에요.)"),
        ce(.elementary, "숫자·요일·날씨", ["요일", "Days of the Week"], "요일은 Monday(월), Tuesday(화), Wednesday(수), Thursday(목), Friday(금), Saturday(토), Sunday(일)예요. 요일 이름은 항상 대문자로 시작하고, 앞에는 전치사 on을 써요.\n예: A: What day is it today? B: It's Friday. (A: 오늘 무슨 요일이야? B: 금요일이야.)"),
        ce(.elementary, "숫자·요일·날씨", ["월 이름", "Months"], "1월부터 12월까지는 January, February, March, April, May, June, July, August, September, October, November, December예요. 월 이름도 대문자로 시작하고, 월만 말할 때는 앞에 in을 써요.\n예: School starts in March. (학교는 3월에 시작해요.)"),
        ce(.elementary, "숫자·요일·날씨", ["날씨 표현", "Weather"], "날씨를 물을 때는 How's the weather? 또는 What's the weather like?라고 해요. 대답은 It's sunny(맑은), cloudy(흐린), rainy(비 오는), snowy(눈 오는), windy(바람 부는).처럼 해요. 이때 it은 '그것'이라는 뜻이 없는 비인칭 주어예요.\n예: It's cold and windy today. (오늘은 춥고 바람이 불어요.)"),
        ce(.elementary, "숫자·요일·날씨", ["시각 말하기", "Telling Time"], "시각을 물을 때는 What time is it?이라고 하고, It's + 시 + 분.으로 대답해요. 정각은 o'clock, 30분은 half past, 15분은 a quarter past로도 말할 수 있어요.\n예: It's seven thirty. = It's half past seven. (7시 30분이에요.)"),

        // MARK: - 중학교

        ce(.middle, "현재와 과거 시제", ["현재 시제", "Simple Present"], "현재 시제는 현재의 상태, 습관이나 반복되는 일, 일반적인 사실과 진리를 나타내요. 시간표나 일정처럼 정해진 미래의 일에도 써요.\n예: Water boils at 100°C. The train leaves at 9 tomorrow. (물은 100°C에서 끓어요. 기차는 내일 9시에 떠나요.)"),
        ce(.middle, "현재와 과거 시제", ["과거 시제", "Simple Past"], "과거 시제는 이미 끝난 과거의 일을 나타내며 yesterday, last week, ago 같은 말과 자주 써요. 규칙 동사는 -ed를 붙이는데, e로 끝나면 -d만, 자음 + y는 y를 i로 바꾸고 -ed, 단모음 + 단자음으로 끝나면 자음을 한 번 더 쓰고 -ed를 붙여요.\n예: live → lived, study → studied, stop → stopped"),
        ce(.middle, "현재와 과거 시제", ["불규칙 동사", "Irregular Verb"], "불규칙 동사는 과거형과 과거분사형이 -ed 규칙을 따르지 않는 동사예요. 세 형태가 모두 다른 것, 과거형과 과거분사가 같은 것, 세 형태가 모두 같은 것이 있어요.\n예: go-went-gone, make-made-made, put-put-put, read-read-read(과거형은 [red]로 발음)"),
        ce(.middle, "현재와 과거 시제", ["과거 시제의 부정문과 의문문", "did not", "Did question"], "일반동사 과거 시제를 부정할 때는 did not(didn't) + 동사원형을, 의문문은 Did + 주어 + 동사원형 ~?을 써요. 주어의 인칭과 상관없이 did를 쓰고, 뒤에 오는 동사는 과거형이 아니라 원형이에요.\n예: A: Did you see the movie? B: No, I didn't. I didn't have time. (A: 그 영화 봤어? B: 아니, 시간이 없었어.)"),
        ce(.middle, "현재와 과거 시제", ["be동사의 과거형", "Past Tense of Be", "was와 were"], "be동사의 과거형은 was와 were예요. I와 3인칭 단수 주어에는 was, you와 복수 주어에는 were를 써요. 부정은 wasn't, weren't이고 의문문은 Was/Were를 주어 앞에 둬요.\n예: We were at the library yesterday. (우리는 어제 도서관에 있었어요.)"),

        ce(.middle, "미래와 진행 시제", ["미래 시제 will", "Future Tense", "will"], "will + 동사원형은 미래의 일이나 예측, 말하는 순간 정한 의지를 나타내요. 부정은 will not(won't)이고, 의문문은 Will + 주어 + 동사원형 ~?이에요.\n예: I'll help you with your homework. It will rain tomorrow. (숙제 도와줄게. 내일 비가 올 거야.)"),
        ce(.middle, "미래와 진행 시제", ["be going to 미래 표현", "be going to"], "be going to + 동사원형은 미리 계획한 일이나 지금 보이는 근거가 있는 예측을 나타내요. be동사는 주어에 맞게 바꿔 써요.\n예: I'm going to visit my grandma this weekend. Look at the clouds! It's going to rain. (이번 주말에 할머니 댁에 갈 거야. 구름 좀 봐! 비가 오겠어.)"),
        ce(.middle, "미래와 진행 시제", ["현재진행형", "Present Progressive", "Present Continuous"], "현재진행형은 be동사(am/are/is) + 동사-ing로, 지금 하고 있는 동작을 나타내요. -ing를 붙일 때 e로 끝나면 e를 빼고, 단모음 + 단자음이면 자음을 하나 더 쓰고, ie로 끝나면 ie를 y로 바꿔요.\n예: make → making, run → running, lie → lying / She is reading a book now. (그녀는 지금 책을 읽고 있어요.)"),
        ce(.middle, "미래와 진행 시제", ["과거진행형", "Past Progressive"], "과거진행형은 was/were + 동사-ing로, 과거 어느 순간에 진행 중이던 동작을 나타내요. 다른 일이 일어났을 때 하고 있던 일을 말할 때 when과 자주 함께 써요.\n예: I was taking a shower when you called. (네가 전화했을 때 나는 샤워하고 있었어.)"),
        ce(.middle, "미래와 진행 시제", ["진행형으로 쓰지 않는 동사", "Stative Verb", "상태동사"], "know, like, love, want, believe, own처럼 상태나 감정을 나타내는 동사는 보통 진행형으로 쓰지 않아요. 다만 have가 '먹다', '시간을 보내다'처럼 동작을 뜻할 때는 진행형이 가능해요.\n예: I know the answer. (○) I am knowing the answer. (×) / We are having lunch. (○)"),

        ce(.middle, "조동사", ["조동사", "Modal Verb", "Auxiliary Verb"], "조동사는 동사 앞에서 능력, 허가, 의무, 추측 같은 의미를 더해 주는 말이에요. 조동사 뒤에는 항상 동사원형이 오고, 주어가 3인칭 단수여도 조동사에 -s를 붙이지 않아요. 부정은 조동사 뒤에 not을 붙여요.\n예: She can speak Chinese. (○) She cans speaks Chinese. (×)"),
        ce(.middle, "조동사", ["조동사 can", "can", "be able to"], "can은 '~할 수 있다'(능력), '~해도 된다'(허가)를 나타내요. 능력의 can은 be able to로 바꿀 수 있고, 미래의 능력은 will be able to로 써요. 과거형은 could예요.\n예: I can ride a bike. = I am able to ride a bike. Can I use your pen? (나는 자전거를 탈 수 있어요. 펜 좀 써도 될까요?)"),
        ce(.middle, "조동사", ["조동사 may", "may"], "may는 '~해도 된다'(허가)와 '~일지도 모른다'(약한 추측)를 나타내요. May I ~?는 Can I ~?보다 공손하게 허락을 구하는 표현이에요.\n예: May I come in? She may be at home now. (들어가도 될까요? 그녀는 지금 집에 있을지도 몰라요.)"),
        ce(.middle, "조동사", ["must와 have to", "must", "have to"], "must와 have to는 '~해야 한다'라는 의무를 나타내요. 하지만 부정형은 뜻이 달라서 must not은 '~하면 안 된다'(금지), don't have to는 '~할 필요가 없다'(불필요)예요. must는 '~임에 틀림없다'라는 강한 추측도 나타내요.\n예: You must not swim here. You don't have to come early. (여기서 수영하면 안 돼요. 일찍 올 필요는 없어요.)"),
        ce(.middle, "조동사", ["조동사 should", "should"], "should는 '~하는 게 좋겠다', '~해야 한다'라는 뜻으로 충고나 권유를 할 때 써요. must보다 부드러운 표현이에요. 부정은 should not(shouldn't)이에요.\n예: You should see a doctor. You shouldn't stay up late. (병원에 가 보는 게 좋겠어. 늦게까지 깨어 있으면 안 돼.)"),
        ce(.middle, "조동사", ["정중한 요청과 제안", "Could you ~?", "Would you like ~?"], "Could you ~?나 Would you ~?는 Can you ~?보다 공손하게 부탁하는 표현이에요. Would you like + 명사/to부정사 ~?는 '~하시겠어요?'라고 정중하게 권할 때 써요. 이때 could와 would는 과거의 뜻이 아니에요.\n예: Could you open the window? Would you like some tea? (창문 좀 열어 주시겠어요? 차 좀 드시겠어요?)"),

        ce(.middle, "to부정사", ["to부정사", "To-infinitive"], "to부정사는 to + 동사원형 형태로, 문장에서 명사, 형용사, 부사처럼 쓰여요. 동사의 성질을 가지고 있어서 뒤에 목적어나 수식어를 거느릴 수 있어요. 부정은 to 앞에 not을 붙여요.\n예: I decided not to give up. (나는 포기하지 않기로 결심했어요.)"),
        ce(.middle, "to부정사", ["to부정사의 명사적 용법", "Infinitive as Noun"], "to부정사가 '~하는 것'이라는 뜻으로 주어, 목적어, 보어 자리에 쓰이는 것을 명사적 용법이라고 해요. 주어가 길면 가주어 it을 앞에 두고 to부정사를 뒤로 보내요.\n예: It is fun to learn English. (영어를 배우는 것은 재미있어요.) My dream is to be a pilot. (내 꿈은 조종사가 되는 거예요.)"),
        ce(.middle, "to부정사", ["to부정사의 형용사적 용법", "Infinitive as Adjective"], "to부정사가 명사 뒤에서 '~할', '~하는'이라는 뜻으로 명사를 꾸며 주는 것을 형용사적 용법이라고 해요. -thing으로 끝나는 대명사는 형용사 + to부정사 순서로 꾸며요.\n예: I need something cold to drink. (나는 마실 차가운 무언가가 필요해요.)"),
        ce(.middle, "to부정사", ["to부정사의 부사적 용법", "Infinitive as Adverb"], "to부정사가 동사나 형용사를 꾸며 목적(~하기 위해), 감정의 원인(~해서), 결과(…해서 결국 ~하다), 판단의 근거(~하다니) 등을 나타내는 것을 부사적 용법이라고 해요.\n예: I went to the store to buy milk. (우유를 사려고 가게에 갔어요.) I'm glad to see you. (만나서 기뻐요.)"),
        ce(.middle, "to부정사", ["to부정사를 목적어로 쓰는 동사", "want to", "decide to"], "want, hope, wish, plan, decide, expect, promise, agree, need, learn처럼 앞으로 할 일과 관련된 동사는 목적어로 to부정사를 써요.\n예: We plan to travel to Jeju. (우리는 제주도로 여행 갈 계획이에요.) I want playing. (×) → I want to play. (○)"),
        ce(.middle, "to부정사", ["too ~ to와 enough to", "too to", "enough to"], "too + 형용사/부사 + to부정사는 '너무 ~해서 …할 수 없다'라는 뜻으로 so ~ that + 주어 + can't로 바꿀 수 있어요. 형용사/부사 + enough + to부정사는 '…할 만큼 충분히 ~하다'라는 뜻이에요.\n예: He is too young to drive. = He is so young that he can't drive. / She is tall enough to reach the shelf."),

        ce(.middle, "동명사", ["동명사", "Gerund"], "동명사는 동사원형 + -ing 형태로 '~하는 것'이라는 뜻의 명사 역할을 해요. 주어, 목적어, 보어, 전치사의 목적어로 쓰이고, 주어로 쓰이면 단수 취급해요.\n예: Reading books is my hobby. (책 읽기가 내 취미예요.) Thank you for helping me. (도와줘서 고마워요.)"),
        ce(.middle, "동명사", ["동명사를 목적어로 쓰는 동사", "enjoy -ing", "finish -ing"], "enjoy, finish, mind, avoid, give up, keep, practice, quit, deny, consider 같은 동사는 목적어로 동명사를 써요. 이미 하고 있거나 해 온 일과 관련된 경우가 많아요.\n예: I enjoy playing the guitar. (나는 기타 치는 것을 즐겨요.) Would you mind opening the door? (문 좀 열어 주실래요?)"),
        ce(.middle, "동명사", ["목적어에 따라 뜻이 달라지는 동사", "remember to와 remember -ing", "stop to와 stop -ing"], "remember와 forget은 to부정사가 오면 '(앞으로) ~할 것을', 동명사가 오면 '(과거에) ~한 것을'이라는 뜻이에요. try to는 '~하려고 노력하다', try -ing는 '시험 삼아 ~해 보다'예요. stop -ing는 '~하던 것을 멈추다'이고, stop to는 '~하기 위해 멈추다'로 이때 to부정사는 목적어가 아니라 목적을 나타내요.\n예: Remember to lock the door. (문 잠그는 것 잊지 마.)"),
        ce(.middle, "동명사", ["동명사 관용 표현", "look forward to -ing", "be busy -ing"], "look forward to -ing(~하기를 고대하다), be used to -ing(~에 익숙하다), be busy -ing(~하느라 바쁘다), How about -ing?(~하는 게 어때?), feel like -ing(~하고 싶다) 같은 관용 표현이 있어요. look forward to와 be used to의 to는 전치사라서 뒤에 동명사가 와요.\n예: I'm looking forward to seeing you. (만나기를 고대하고 있어요.)"),

        ce(.middle, "형용사와 부사", ["빈도부사", "Adverb of Frequency"], "빈도부사는 어떤 일이 얼마나 자주 일어나는지 나타내요. 빈도가 높은 순으로 always, usually, often, sometimes, never 등이 있어요. 보통 be동사와 조동사 뒤, 일반동사 앞에 와요.\n예: She is always kind. I usually get up at 7. (그녀는 항상 친절해요. 나는 보통 7시에 일어나요.)"),
        ce(.middle, "형용사와 부사", ["수량 형용사", "many와 much", "a few와 a little"], "셀 수 있는 명사에는 many, a few(약간 있는), few(거의 없는)를, 셀 수 없는 명사에는 much, a little(약간 있는), little(거의 없는)을 써요. a lot of와 lots of는 둘 다에 쓸 수 있어요.\n예: I have a few friends here. There is little water in the bottle. (여기 친구가 몇 명 있어요. 병에 물이 거의 없어요.)"),
        ce(.middle, "형용사와 부사", ["some과 any", "some", "any"], "some과 any는 '약간의, 몇몇의'라는 뜻이에요. some은 주로 긍정문에, any는 부정문과 의문문에 써요. 다만 권유하거나 부탁하는 의문문에는 some을 써요.\n예: I don't have any money. Would you like some cookies? (나는 돈이 하나도 없어요. 쿠키 좀 드실래요?)"),

        ce(.middle, "비교 표현", ["비교급", "Comparative"], "비교급은 두 대상을 비교하여 '더 ~한'을 나타내며, 형용사/부사 + -er + than 형태예요. 3음절 이상이거나 -ful, -ous 등으로 끝나는 단어는 앞에 more를 붙여요. big → bigger처럼 단모음 + 단자음은 자음을 겹치고, happy → happier처럼 자음 + y는 y를 i로 바꿔요.\n예: My bag is heavier than yours. This book is more interesting than that one."),
        ce(.middle, "비교 표현", ["최상급", "Superlative"], "최상급은 셋 이상 중에서 '가장 ~한'을 나타내며, the + 형용사/부사 + -est 또는 the most + 형용사/부사 형태예요. 범위는 장소나 집단 앞에 in, 복수 명사 앞에 of를 써서 나타내요.\n예: Seoul is the biggest city in Korea. She is the most famous of the three singers."),
        ce(.middle, "비교 표현", ["불규칙 비교 변화", "Irregular Comparison"], "몇몇 형용사와 부사는 비교급과 최상급이 불규칙하게 변해요. good/well - better - best, bad/ill - worse - worst, many/much - more - most, little - less - least가 대표적이에요.\n예: Your idea is better than mine. (네 생각이 내 것보다 나아.)"),
        ce(.middle, "비교 표현", ["원급 비교", "as ~ as"], "as + 형용사/부사 원급 + as는 '~만큼 …한'이라는 뜻으로 두 대상의 정도가 같음을 나타내요. 부정형 not as(so) ~ as는 '~만큼 …하지 않은'이라는 뜻이에요. as ~ as possible은 '가능한 한 ~하게'예요.\n예: Tom is as tall as his father. Call me as soon as possible. (톰은 아빠만큼 키가 커요. 가능한 한 빨리 전화 줘.)"),
        ce(.middle, "비교 표현", ["비교급 강조", "much + 비교급"], "비교급을 강조해 '훨씬 더 ~한'이라고 할 때는 much, even, far, still, a lot을 비교급 앞에 써요. very는 비교급을 꾸밀 수 없어요.\n예: This phone is much cheaper than that one. (○) This phone is very cheaper than that one. (×)"),
        ce(.middle, "비교 표현", ["the 비교급, the 비교급", "The more, the better"], "The + 비교급 + 주어 + 동사, the + 비교급 + 주어 + 동사는 '~하면 할수록 더 …하다'라는 뜻이에요. 비교급 + and + 비교급은 '점점 더 ~한'이라는 뜻이에요.\n예: The more you practice, the better you get. It's getting colder and colder. (연습할수록 더 잘하게 돼요. 점점 더 추워지고 있어요.)"),

        ce(.middle, "접속사", ["등위접속사", "Coordinating Conjunction"], "등위접속사는 단어와 단어, 구와 구, 절과 절을 대등하게 연결해요. and(그리고), but(그러나), or(또는), so(그래서)가 대표적이고, for, nor, yet도 있어요.\n예: I was tired, so I went to bed early. (피곤해서 일찍 잤어요.)"),
        ce(.middle, "접속사", ["접속사 that", "Noun Clause that"], "접속사 that은 '~라는 것'이라는 뜻의 명사절을 이끌어 주어, 목적어, 보어로 쓰여요. 목적어로 쓰인 that은 생략할 수 있어요.\n예: I think (that) he is honest. (나는 그가 정직하다고 생각해요.) The problem is that we have no time. (문제는 우리에게 시간이 없다는 거예요.)"),
        ce(.middle, "접속사", ["시간의 접속사", "Conjunctions of Time"], "when(~할 때), while(~하는 동안), before(~하기 전에), after(~한 후에), until(~할 때까지)은 시간을 나타내는 부사절을 이끌어요. 시간과 조건의 부사절에서는 미래의 일도 현재 시제로 써요.\n예: I'll call you when I get home. (○) I'll call you when I will get home. (×) (집에 도착하면 전화할게.)"),
        ce(.middle, "접속사", ["이유의 접속사", "because와 because of"], "because, since, as는 '~ 때문에'라는 이유를 나타내는 접속사로 뒤에 주어 + 동사가 와요. because of 뒤에는 명사(구)가 와요. 결과를 말할 때는 so를 써요.\n예: I stayed home because it rained. = I stayed home because of the rain. (비 때문에 집에 있었어요.)"),
        ce(.middle, "접속사", ["조건의 접속사", "if와 unless"], "if는 '만약 ~라면', unless는 '만약 ~하지 않으면'(= if ~ not)이라는 뜻이에요. 조건의 부사절에서도 미래의 일은 현재 시제로 나타내요. unless 자체에 부정의 뜻이 있으므로 not을 또 쓰지 않아요.\n예: Unless you hurry, you will miss the bus. = If you don't hurry, you will miss the bus."),
        ce(.middle, "접속사", ["양보의 접속사", "although와 though"], "although와 though는 '비록 ~이지만'이라는 뜻으로 예상과 반대되는 내용을 연결해요. 같은 뜻의 전치사 despite, in spite of 뒤에는 명사(구)가 와요.\n예: Although it was cold, we went swimming. = Despite the cold, we went swimming. (추웠지만 우리는 수영하러 갔어요.)"),
        ce(.middle, "접속사", ["상관접속사", "Correlative Conjunction"], "상관접속사는 두 단어가 짝을 이루는 접속사예요. both A and B(A와 B 둘 다)는 복수 취급하고, either A or B, neither A nor B, not only A but also B(= B as well as A)는 동사를 B에 맞춰요.\n예: Not only I but also my sisters like cats. Either you or he has to go."),

        ce(.middle, "수동태", ["수동태", "Passive Voice"], "수동태는 주어가 동작을 '받는' 것을 나타내며 be동사 + 과거분사(p.p.) 형태예요. 능동태의 목적어가 주어가 되고, 행위자는 by + 목적격으로 나타내는데 중요하지 않거나 알 수 없으면 생략해요. 목적어가 없는 자동사는 수동태로 쓸 수 없어요.\n예: The window was broken by Tom. (창문은 톰에 의해 깨졌어요.)"),
        ce(.middle, "수동태", ["수동태의 시제와 형태", "Passive Tenses"], "수동태의 시제는 be동사로 나타내요. 과거는 was/were + p.p., 미래는 will be + p.p., 조동사가 있으면 조동사 + be + p.p.예요. 부정문은 be동사 뒤에 not을 쓰고, 의문문은 be동사를 주어 앞에 둬요.\n예: The bridge will be built next year. This rule must be followed. Was it made in Korea?"),
        ce(.middle, "수동태", ["by 이외의 전치사를 쓰는 수동태", "be interested in"], "몇몇 수동태 표현은 by 대신 다른 전치사를 써요. be interested in(~에 관심이 있다), be covered with(~로 덮여 있다), be filled with(~로 가득 차 있다), be known for(~로 유명하다), be made of(재료의 성질이 남음), be made from(재료의 성질이 변함) 등이 있어요.\n예: The desk is made of wood. Cheese is made from milk."),

        ce(.middle, "관계대명사", ["관계대명사", "Relative Pronoun"], "관계대명사는 접속사와 대명사 역할을 함께 하면서 앞의 명사(선행사)를 꾸미는 절을 이끌어요. 선행사가 사람이면 who, 사물이나 동물이면 which를 쓰고, that은 둘 다에 쓸 수 있어요.\n예: I have a friend who lives in Canada. (나는 캐나다에 사는 친구가 있어요.)"),
        ce(.middle, "관계대명사", ["주격 관계대명사", "Subject Relative Pronoun"], "관계대명사가 관계절 안에서 주어 역할을 하면 주격 관계대명사예요. 뒤에 바로 동사가 오고, 그 동사는 선행사의 수에 맞춰요.\n예: The girl who is singing on the stage is my cousin. The books that are on the table are mine."),
        ce(.middle, "관계대명사", ["목적격 관계대명사", "Object Relative Pronoun"], "관계대명사가 관계절 안에서 목적어 역할을 하면 목적격 관계대명사로, who(m), which, that을 써요. 목적격 관계대명사는 생략할 수 있고, 관계절은 목적어가 빠진 상태로 남아요.\n예: This is the movie (which) I watched yesterday. (이건 내가 어제 본 영화예요.)"),
        ce(.middle, "관계대명사", ["소유격 관계대명사", "whose"], "whose는 선행사가 관계절 안에서 '~의'라는 소유의 뜻을 가질 때 써요. 선행사가 사람이든 사물이든 whose를 쓰고, 뒤에 명사가 바로 와요.\n예: I know a boy whose father is a pilot. (나는 아빠가 조종사인 소년을 알아요.)"),
        ce(.middle, "관계대명사", ["관계대명사 what", "what 관계대명사"], "관계대명사 what은 선행사를 포함하고 있어서 '~하는 것'이라는 뜻이며, the thing(s) which(that)와 같아요. 앞에 선행사가 없고, what절은 문장에서 주어, 목적어, 보어로 쓰여요.\n예: What I want is a new bike. = The thing that I want is a new bike. (내가 원하는 것은 새 자전거예요.)"),

        ce(.middle, "여러 가지 문장", ["감탄문", "Exclamatory Sentence"], "감탄문은 기쁨, 놀람 같은 강한 감정을 나타내는 문장이에요. What 감탄문은 What + a(n) + 형용사 + 명사 + 주어 + 동사!, How 감탄문은 How + 형용사/부사 + 주어 + 동사! 순서예요. 뒤의 주어와 동사는 생략할 수 있어요.\n예: What a beautiful day (it is)! How fast he runs! (정말 아름다운 날이야! 그는 정말 빨리 달리는구나!)"),
        ce(.middle, "여러 가지 문장", ["부가의문문", "Tag Question"], "부가의문문은 문장 끝에 붙여 확인하거나 동의를 구하는 짧은 의문문이에요. 앞 문장이 긍정이면 부정으로, 부정이면 긍정으로 쓰고, 주어는 대명사로 바꿔요. be동사와 조동사는 그대로, 일반동사는 do/does/did를 써요. 명령문은 will you?, Let's 문장은 shall we?를 붙여요.\n예: You like pizza, don't you? She can't swim, can she?"),
        ce(.middle, "여러 가지 문장", ["부정의문문과 대답", "Negative Question"], "Don't you ~?처럼 부정으로 묻는 의문문에도 대답 내용이 긍정이면 Yes, 부정이면 No로 대답해요. 우리말 '네/아니요'와 반대로 느껴질 수 있어 주의해야 해요.\n예: A: Don't you like milk? B: Yes, I do. (아니, 좋아해.) / No, I don't. (응, 안 좋아해.)"),
        ce(.middle, "여러 가지 문장", ["간접의문문", "Indirect Question"], "간접의문문은 의문문이 다른 문장의 일부(주로 목적어)가 된 것이에요. 의문사가 있으면 의문사 + 주어 + 동사, 의문사가 없으면 if/whether + 주어 + 동사 순서로 써요. 다만 think, believe 같은 동사가 쓰인 의문문에서는 의문사를 문장 맨 앞으로 보내요.\n예: Do you know where she lives? Do you know if he is home? What do you think he wants?"),

        // MARK: - 고등학교

        ce(.high, "문장의 5형식", ["문장의 5형식", "Five Sentence Patterns", "문장 형식"], "영어 문장은 동사 뒤에 어떤 요소가 오는지에 따라 다섯 가지 형식으로 나눌 수 있어요. 1형식 S+V, 2형식 S+V+C, 3형식 S+V+O, 4형식 S+V+I.O.+D.O., 5형식 S+V+O+O.C.이에요. 같은 동사도 쓰임에 따라 형식이 달라질 수 있어요.\n예: He made a cake.(3형식) / He made me a cake.(4형식) / He made me happy.(5형식)"),
        ce(.high, "문장의 5형식", ["1형식 문장", "S+V"], "1형식은 주어와 동사만으로 뜻이 완성되는 문장이에요. 장소나 시간을 나타내는 부사구가 붙어도 문장 형식에는 들어가지 않아요. There is/are 구문도 1형식으로 봐요.\n예: The sun rises in the east. There are three apples on the table."),
        ce(.high, "문장의 5형식", ["2형식 문장", "S+V+C", "감각동사"], "2형식은 주어를 설명하는 보어가 필요한 문장이에요. be, become, get, seem처럼 상태나 변화를 뜻하는 동사와 look, sound, smell, taste, feel 같은 감각동사가 쓰여요. 보어 자리에는 부사가 아니라 형용사나 명사가 와요.\n예: You look happy. (○) You look happily. (×) This soup tastes good."),
        ce(.high, "문장의 5형식", ["3형식 문장", "S+V+O"], "3형식은 주어, 동사, 목적어로 이루어진 문장이에요. discuss, marry, enter, reach, resemble처럼 우리말로는 '~에 대해', '~와'가 붙어 보여도 전치사 없이 바로 목적어를 쓰는 타동사에 주의해요.\n예: We discussed the plan. (○) We discussed about the plan. (×)"),
        ce(.high, "문장의 5형식", ["4형식 문장", "S+V+IO+DO", "수여동사"], "4형식은 '~에게(간접목적어) …을(직접목적어) 주다'라는 뜻의 문장으로 give, send, show, buy, make, ask 같은 수여동사를 써요. 3형식으로 바꿀 때는 직접목적어를 앞으로 보내고 간접목적어 앞에 전치사를 붙이는데, give류는 to, buy·make류는 for, ask는 of를 써요.\n예: He gave me a book. → He gave a book to me."),
        ce(.high, "문장의 5형식", ["5형식 문장", "S+V+O+OC", "목적격보어"], "5형식은 목적어 뒤에 목적어를 설명하는 목적격보어가 오는 문장이에요. 목적격보어로는 명사, 형용사, to부정사, 동사원형, 분사가 올 수 있고, 어떤 형태가 오는지는 동사가 정해요.\n예: They elected him captain. The news made me sad. I want you to come. (그들은 그를 주장으로 뽑았어요. 그 소식은 나를 슬프게 했어요. 네가 왔으면 좋겠어.)"),
        ce(.high, "문장의 5형식", ["사역동사", "Causative Verb"], "make, have, let은 '~가 …하게 하다'라는 뜻의 사역동사로, 목적어가 동작을 하는 관계이면 목적격보어로 동사원형을 써요. have와 get은 목적어가 동작을 받는 관계이면 과거분사를 써요. get은 능동 관계일 때 to부정사를 쓰고, help는 동사원형과 to부정사를 모두 써요.\n예: Mom made me clean my room. I had my hair cut. I got him to fix the car."),
        ce(.high, "문장의 5형식", ["지각동사", "Perception Verb"], "see, watch, hear, listen to, feel, notice 같은 지각동사는 목적격보어로 동사원형이나 현재분사(-ing)를 써요. 현재분사를 쓰면 동작이 진행 중인 느낌이 강해요. 목적어가 동작을 받는 관계이면 과거분사를 써요.\n예: I saw him cross(crossing) the street. I heard my name called. (나는 그가 길을 건너는 것을 봤어요. 내 이름이 불리는 것을 들었어요.)"),

        ce(.high, "완료시제", ["현재완료", "Present Perfect"], "현재완료는 have/has + 과거분사로, 과거에 일어난 일이 현재와 연결되어 있음을 나타내요. 쓰임에 따라 완료(막 ~했다), 경험(~한 적이 있다), 계속(~해 왔다), 결과(~해 버렸다)로 나눠요.\n예: I have just finished my homework.(완료) Have you ever been to Japan?(경험) She has lived here for ten years.(계속) He has lost his key.(결과)"),
        ce(.high, "완료시제", ["현재완료와 과거 시제의 차이", "Present Perfect vs Past"], "과거 시제는 현재와 끊어진 과거의 사실만 말하고, 현재완료는 그 일이 현재까지 이어지거나 영향을 준다는 점을 말해요. 그래서 yesterday, ago, last year, When ~? 처럼 분명한 과거 시점을 나타내는 말은 현재완료와 함께 쓰지 않아요.\n예: I lost my phone yesterday. (○) I have lost my phone yesterday. (×)"),
        ce(.high, "완료시제", ["현재완료진행형", "Present Perfect Progressive"], "현재완료진행형은 have/has been + -ing로, 과거에 시작된 동작이 지금까지 계속 진행 중임을 강조해요. for(~ 동안), since(~ 이후로)와 자주 함께 써요.\n예: It has been raining since this morning. (오늘 아침부터 계속 비가 오고 있어요.)"),
        ce(.high, "완료시제", ["과거완료", "Past Perfect", "대과거"], "과거완료는 had + 과거분사로, 과거의 어느 시점보다 먼저 일어난 일이나 그때까지 이어진 일을 나타내요. 두 과거 사건 중 더 먼저 일어난 일을 나타내는 것을 대과거라고도 해요.\n예: When I arrived at the station, the train had already left. (내가 역에 도착했을 때 기차는 이미 떠났어요.)"),
        ce(.high, "완료시제", ["미래완료", "Future Perfect"], "미래완료는 will have + 과거분사로, 미래의 어느 시점까지 완료되거나 경험하게 될 일을 나타내요. by(~까지), by the time 같은 표현과 자주 써요.\n예: I will have finished the report by Friday. (금요일까지는 보고서를 끝냈을 거예요.)"),

        ce(.high, "가정법", ["가정법 과거", "Second Conditional", "Subjunctive Past"], "가정법 과거는 현재 사실과 반대되거나 일어날 가능성이 낮은 일을 가정해요. If + 주어 + 과거동사, 주어 + would/could/might + 동사원형 형태이고, be동사는 주어와 상관없이 were를 쓰는 것이 원칙이에요. 형태는 과거지만 뜻은 현재예요.\n예: If I were a bird, I could fly to you. (내가 새라면 너에게 날아갈 수 있을 텐데.)"),
        ce(.high, "가정법", ["가정법 과거완료", "Third Conditional"], "가정법 과거완료는 과거 사실과 반대되는 일을 가정하며, If + 주어 + had + p.p., 주어 + would/could/might + have + p.p. 형태예요.\n예: If I had studied harder, I would have passed the exam. (내가 더 열심히 공부했더라면 시험에 합격했을 텐데.) → 실제로는 열심히 하지 않아서 떨어졌다는 뜻이에요."),
        ce(.high, "가정법", ["혼합가정법", "Mixed Conditional"], "혼합가정법은 과거의 일이 현재에 영향을 주는 경우로, if절은 가정법 과거완료, 주절은 가정법 과거를 써요. 주절에 now, today 같은 현재 표현이 자주 나와요.\n예: If I had taken the medicine, I would feel better now. (그 약을 먹었더라면 지금 몸이 나을 텐데.)"),
        ce(.high, "가정법", ["I wish 가정법", "I wish"], "I wish + 가정법 과거는 '~라면 좋을 텐데'라는 현재의 이루기 어려운 소망을, I wish + 가정법 과거완료는 '~했더라면 좋았을 텐데'라는 과거에 대한 후회를 나타내요.\n예: I wish I knew her number. (그녀의 번호를 알면 좋을 텐데.) I wish I had listened to you. (네 말을 들었더라면 좋았을 텐데.)"),
        ce(.high, "가정법", ["as if 가정법", "as if"], "as if(as though) + 가정법 과거는 '마치 ~인 것처럼'(주절과 같은 때의 반대 사실), as if + 가정법 과거완료는 '마치 ~였던 것처럼'(주절보다 앞선 때의 반대 사실)을 나타내요.\n예: He talks as if he knew everything. (그는 마치 모든 것을 아는 것처럼 말해요.) She looks as if she had seen a ghost. (그녀는 마치 유령이라도 본 것 같은 얼굴이에요.)"),
        ce(.high, "가정법", ["if 생략 도치", "Inverted Conditional"], "가정법 문장에서 if를 생략하면 주어와 동사(were, had, should)의 순서가 바뀌어요. 격식 있는 글에서 자주 쓰여요.\n예: If I were you → Were I you / If he had known → Had he known / If you should need help → Should you need help"),
        ce(.high, "가정법", ["without 가정법", "but for", "if it were not for"], "without과 but for는 '~이 없다면/없었다면'이라는 뜻으로 가정법에 쓰여요. 주절이 가정법 과거이면 If it were not for(= Were it not for), 가정법 과거완료이면 If it had not been for(= Had it not been for)로 바꿀 수 있어요.\n예: Without water, we couldn't live. = If it were not for water, we couldn't live."),

        ce(.high, "분사와 분사구문", ["분사", "Participle", "현재분사와 과거분사"], "분사는 동사가 형용사처럼 쓰이는 형태예요. 현재분사(-ing)는 능동·진행(~하는, ~하고 있는)을, 과거분사(p.p.)는 수동·완료(~된, ~당한)를 나타내요. 분사가 혼자 꾸미면 명사 앞에, 다른 말과 함께 길어지면 명사 뒤에 와요.\n예: a sleeping baby, fallen leaves, a car made in Germany (자고 있는 아기, 떨어진 낙엽, 독일에서 만들어진 차)"),
        ce(.high, "분사와 분사구문", ["감정을 나타내는 분사", "exciting과 excited"], "감정 동사로 만든 분사는 감정을 일으키면 현재분사(-ing), 감정을 느끼면 과거분사(p.p.)를 써요. 보통 사물에는 -ing, 사람에는 p.p.를 쓰는 경우가 많지만, 사람이 남에게 그런 감정을 줄 때는 -ing를 써요.\n예: The game was exciting. I was excited. / He is boring.(그는 지루한 사람이에요.) I am bored.(나는 지루해요.)"),
        ce(.high, "분사와 분사구문", ["분사구문", "Participial Construction"], "분사구문은 부사절을 분사로 줄여 쓴 구문이에요. 접속사를 없애고, 부사절과 주절의 주어가 같으면 주어도 없앤 뒤, 동사를 -ing로 바꿔요. 부정은 분사 앞에 not을 쓰고, 문장 앞의 Being이나 Having been은 흔히 생략해요.\n예: When I walked down the street, I met Jane. → Walking down the street, I met Jane."),
        ce(.high, "분사와 분사구문", ["분사구문의 의미", "Meaning of Participial Construction"], "분사구문은 문맥에 따라 시간(~할 때), 이유(~해서), 조건(~하면), 양보(~이지만), 동시동작(~하면서), 연속동작(~하고 나서 …하다)의 의미를 나타내요. 의미를 분명히 하려고 접속사를 남기기도 해요.\n예: Feeling tired, I went to bed early.(이유) He sat on the sofa, watching TV.(동시동작)"),
        ce(.high, "분사와 분사구문", ["독립분사구문", "Absolute Participial Construction"], "부사절의 주어가 주절의 주어와 다르면 분사구문 앞에 주어를 남겨 두는데, 이를 독립분사구문이라고 해요. 주어가 일반 사람이라 생략된 Generally speaking, Frankly speaking, Judging from 같은 표현은 비인칭 독립분사구문이라고 해요.\n예: It being sunny, we went on a picnic. Frankly speaking, I don't like it."),
        ce(.high, "분사와 분사구문", ["with + 명사 + 분사", "with 분사구문"], "with + 명사 + 분사는 '~가 …한 채로'라는 뜻으로 동시 상황을 나타내요. 명사와 분사가 능동 관계이면 현재분사, 수동 관계이면 과거분사를 써요.\n예: She was listening with her eyes closed. He ran with his dog following him. (그녀는 눈을 감은 채 듣고 있었어요. 그는 개가 뒤따르는 채로 달렸어요.)"),
        ce(.high, "분사와 분사구문", ["완료분사구문", "Perfect Participle"], "부사절의 시제가 주절보다 앞서면 Having + p.p. 형태의 완료분사구문을 써요. 수동이면 Having been + p.p.가 되고, 이때 Having been은 생략할 수 있어요.\n예: Having finished my homework, I went out to play. (숙제를 끝낸 후 나는 놀러 나갔어요.)"),

        ce(.high, "관계사 심화", ["관계부사", "Relative Adverb"], "관계부사는 접속사와 부사 역할을 함께 하며 when(시간), where(장소), why(이유), how(방법)가 있어요. 관계부사는 전치사 + which로 바꿀 수 있고, 뒤에는 완전한 문장이 와요. the way와 how는 함께 쓰지 않고 둘 중 하나만 써요.\n예: This is the house where I was born. = This is the house in which I was born. / This is how(the way) I solved it."),
        ce(.high, "관계사 심화", ["관계사의 계속적 용법", "Non-restrictive Relative Clause"], "관계사 앞에 콤마(,)를 찍으면 계속적 용법으로, 선행사에 대한 정보를 덧붙여요. 접속사 + 대명사(and he, but it 등)로 바꿔 해석하고, that과 what은 계속적 용법으로 쓸 수 없어요. which는 앞 문장 전체를 받을 수도 있어요.\n예: I have a brother, who lives in Seoul. He said nothing, which made her angry."),
        ce(.high, "관계사 심화", ["전치사 + 관계대명사", "Preposition + Relative Pronoun"], "관계절의 전치사는 관계대명사 앞으로 옮길 수 있어요. 이때는 whom이나 which만 쓸 수 있고 that은 쓸 수 없으며, 관계대명사를 생략할 수도 없어요.\n예: This is the girl about whom I told you. (○) This is the girl about that I told you. (×) = This is the girl (who(m)) I told you about."),
        ce(.high, "관계사 심화", ["복합관계대명사", "Compound Relative Pronoun", "whoever", "whatever"], "복합관계대명사는 관계대명사 + ever 형태로 선행사를 포함해요. whoever는 '~하는 누구든지'(= anyone who) 또는 '누가 ~하더라도'(= no matter who), whatever는 '~하는 무엇이든지' 또는 '무엇을 ~하더라도'라는 뜻이에요.\n예: Whoever comes first will get a prize. Whatever you do, do your best."),
        ce(.high, "관계사 심화", ["복합관계부사", "Compound Relative Adverb", "whenever", "wherever"], "복합관계부사는 when, where, how + ever 형태예요. whenever는 '~할 때마다/언제 ~하더라도', wherever는 '~하는 곳은 어디든/어디서 ~하더라도', however는 '아무리 ~해도'라는 뜻으로 However + 형용사/부사 + 주어 + 동사 순서로 써요.\n예: However hard it is, I won't give up. (아무리 힘들어도 포기하지 않을 거예요.)"),
        ce(.high, "관계사 심화", ["관계대명사 what과 접속사 that 구별", "what vs that"], "what은 앞에 선행사가 없고 뒤에 주어나 목적어가 빠진 불완전한 문장이 와요. 명사절 접속사 that 뒤에는 완전한 문장이 오고, 관계대명사 that은 앞에 선행사가 있어요. 수능 어법 문제의 단골 출제 포인트예요.\n예: What he said was true.(불완전) / The fact is that he lied.(완전) / This is the book that I bought.(선행사 있음)"),

        ce(.high, "도치와 강조", ["부정어 도치", "Negative Inversion", "도치"], "never, little, hardly, rarely, seldom, not only 같은 부정어(구)가 강조되어 문장 앞에 오면 주어와 동사의 순서가 바뀌어요. 일반동사는 do/does/did + 주어 + 동사원형, 완료형은 have + 주어 + p.p. 순서가 돼요.\n예: Never have I seen such a beautiful sunset. Little did he know the truth."),
        ce(.high, "도치와 강조", ["Only 도치", "Only + 부사구 도치", "Not until 도치"], "only가 이끄는 부사(구·절)가 문장 앞에 오면 주절의 주어와 동사가 도치돼요. Not until ~ 구문도 마찬가지로 주절이 도치돼요.\n예: Only then did I realize my mistake. Not until midnight did she come home. (그때서야 나는 실수를 깨달았어요. 자정이 되어서야 그녀는 집에 왔어요.)"),
        ce(.high, "도치와 강조", ["장소·방향 부사구 도치", "Locative Inversion"], "장소나 방향을 나타내는 부사(구)가 문장 앞에 오면 1형식 동사와 주어가 도치될 수 있어요. 이때 조동사 do를 쓰지 않고 동사를 그대로 주어 앞에 둬요. 단, 주어가 대명사이면 도치하지 않아요.\n예: On the hill stood an old castle. Here comes the bus. / Here it comes. (○) Here comes it. (×)"),
        ce(.high, "도치와 강조", ["so와 neither 도치", "So do I", "Neither do I"], "앞 사람 말에 '나도 그래'라고 동의할 때 긍정문 뒤에는 So + 동사 + 주어, 부정문 뒤에는 Neither(Nor) + 동사 + 주어를 써요. 동사는 앞 문장에 맞춰 be동사, 조동사, do/does/did 중에서 골라요.\n예: A: I'm hungry. B: So am I. / A: I didn't go. B: Neither did I."),
        ce(.high, "도치와 강조", ["It is ~ that 강조구문", "Cleft Sentence"], "It is(was)와 that 사이에 강조하고 싶은 말(주어, 목적어, 부사구)을 넣어 '…한 것은 바로 ~이다'라는 뜻을 만들어요. 강조하는 말이 사람이면 who, 사물이면 which를 that 대신 쓸 수 있어요. 형용사나 동사는 이 구문으로 강조할 수 없어요.\n예: It was Tom that broke the window. It was yesterday that I met her."),
        ce(.high, "도치와 강조", ["조동사 do 강조", "Emphatic do"], "일반동사의 긍정문에서 동사를 강조할 때는 동사 앞에 do/does/did를 쓰고 뒤에 동사원형을 써요. '정말로, 꼭'이라는 뜻을 더해요.\n예: I do love you. She did call me last night. (정말 사랑해. 그녀는 어젯밤에 정말로 전화했어.)"),

        ce(.high, "화법 전환", ["직접화법과 간접화법", "Direct and Indirect Speech", "화법 전환"], "직접화법은 남의 말을 따옴표 안에 그대로 옮기고, 간접화법은 전달하는 사람의 입장에서 바꾸어 전해요. 간접화법으로 바꿀 때는 전달동사(say → say, say to → tell), 인칭대명사, 시제, 시간·장소 부사를 상황에 맞게 바꿔요.\n예: He said to me, \"I am busy.\" → He told me that he was busy."),
        ce(.high, "화법 전환", ["시제 일치", "Sequence of Tenses"], "주절의 동사가 과거이면 종속절의 동사도 과거나 과거완료로 맞추는 것을 시제 일치라고 해요. 하지만 변하지 않는 진리, 현재의 습관, 속담은 현재 시제를, 역사적 사실은 항상 과거 시제를 써요.\n예: He said that he was tired. / The teacher said that the earth goes around the sun. / We learned that Columbus arrived in America in 1492."),
        ce(.high, "화법 전환", ["의문문의 화법 전환", "Reported Question"], "의문문을 간접화법으로 바꿀 때는 전달동사를 ask로 바꾸고, 의문사가 있으면 의문사 + 주어 + 동사, 없으면 if/whether + 주어 + 동사 순서로 써요. 물음표는 쓰지 않아요.\n예: She said to me, \"Where do you live?\" → She asked me where I lived. / He said to me, \"Are you ready?\" → He asked me if I was ready."),
        ce(.high, "화법 전환", ["명령문의 화법 전환", "Reported Command"], "명령문을 간접화법으로 바꿀 때는 전달동사를 tell(지시), ask(부탁), order(명령), advise(충고) 등으로 바꾸고 목적어 + to부정사를 써요. 부정 명령문은 not + to부정사로 바꿔요.\n예: Mom said to me, \"Clean your room.\" → Mom told me to clean my room. / He said to us, \"Don't be late.\" → He told us not to be late."),
        ce(.high, "화법 전환", ["화법 전환과 부사 변화", "Time and Place Changes"], "직접화법을 간접화법으로 바꿀 때 시간·장소 표현도 전달 시점에 맞게 바꿔요. now → then, today → that day, tomorrow → the next day, yesterday → the day before, ago → before, here → there, this → that으로 바뀌어요.\n예: She said, \"I will leave tomorrow.\" → She said that she would leave the next day."),

        ce(.high, "독해 전략", ["주제와 요지 파악", "Main Idea", "Topic and Gist"], "주제는 글이 무엇에 관한 것인지, 요지는 필자가 결국 말하고 싶은 핵심 주장이에요. 글의 처음과 마지막, 그리고 however, therefore, in short 같은 연결어 뒤에 핵심이 나오는 경우가 많아요. 예시나 세부 내용에 끌려 너무 좁거나 넓은 선택지를 고르지 않도록 해요.\n예: However, recent studies show … → 이 뒤에 필자의 진짜 주장이 나올 가능성이 커요."),
        ce(.high, "독해 전략", ["빈칸 추론", "Blank Inference"], "빈칸 추론은 글의 흐름과 핵심 내용을 바탕으로 빈칸에 들어갈 말을 고르는 유형이에요. 빈칸 문장이 주제문인 경우가 많으므로 먼저 주제를 잡고, 빈칸 앞뒤의 연결어, 반복되는 표현, 예시를 근거로 삼아요. 고른 답을 넣어 글 전체와 맞는지 확인해요.\n예: Success depends less on talent than on (   ). → 뒤의 예시가 꾸준한 연습이라면 persistence가 정답 후보예요."),
        ce(.high, "독해 전략", ["글의 순서 배열", "Paragraph Ordering"], "주어진 글 다음에 이어질 (A), (B), (C)의 순서를 정하는 유형이에요. 대명사(this, they), 정관사 the, 연결어(however, for example, as a result), 앞에서 나온 개념을 다시 가리키는 표현이 중요한 단서가 돼요.\n예: (B)가 This problem으로 시작하면, 바로 앞 단락에 그 '문제'가 처음 소개되어 있어야 해요."),
        ce(.high, "독해 전략", ["문장 삽입", "Sentence Insertion"], "주어진 문장이 들어갈 가장 알맞은 위치를 고르는 유형이에요. 주어진 문장의 연결어와 지시어를 먼저 분석하고, 글에서 논리가 끊기거나 갑자기 화제가 바뀌는 곳을 찾아요. 넣은 뒤 앞뒤 문장이 자연스럽게 이어지는지 확인해요.\n예: 주어진 문장이 But this was not always the case.라면 바로 앞에 현재 상황에 대한 설명이 있어야 해요."),
        ce(.high, "독해 전략", ["요약문 완성", "Summary Completion"], "글 전체를 한 문장으로 요약한 문장의 빈칸 (A), (B)에 들어갈 말을 고르는 유형이에요. 요약문을 먼저 읽어 무엇을 찾아야 하는지 파악한 뒤 본문의 핵심 내용과 대응시켜요. 본문 표현이 요약문에서는 다른 말로 바뀌어 있는 점에 주의해요.\n예: 본문의 cooperate가 요약문에서는 collaboration으로 바뀌어 나올 수 있어요."),
